import{_ as r,a0 as a,w as d,s as i,ao as m,I as p,x as e,a1 as s,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"三个快速便捷的命令行小贴士 | LCTT x X-CMD","titleTemplate":false,"description":"三个快速便捷的命令行小贴士 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"三个快速便捷的命令行小贴士 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"三个快速便捷的命令行小贴士 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Quick-n-easy command-line tips","title":"三个快速便捷的命令行小贴士","tag":"201310","desc":""},"relativePath":"201310/Quick-n-easy command-line tips.md","filePath":"[post].md"}'),l={name:"201310/Quick-n-easy command-line tips.md"};function u(c,t,g,f,T,x){const n=a("Link");return d(),i("div",null,[t[11]||(t[11]=m(`<h1 id="三个快速便捷的命令行小贴士" tabindex="-1">三个快速便捷的命令行小贴士 <a class="header-anchor" href="#三个快速便捷的命令行小贴士" aria-label="Permalink to “三个快速便捷的命令行小贴士”">​</a></h1><p>最近几周里，我总是收到人们询问一些快速零散的问题。有时候一个人是在寻找一个有帮助的建议，或者一个具体的命令，或者一个命令行捷径，以完成一个特定的任务。本篇将介绍最近人们向我提出的三个问题，以及完成这些任务的简单方法。</p><p>###第一个场景</p><p><strong>我们要找到那些在过去的一个月中被改动过的文件，并将他们从当前的位置复制到另一个目录中去。</strong></p><p>在这种情况下，能否精确的解决取决于你复制文件的时候是否保持了原来的文件树结构，还是你仅仅只是把所有文件全部复制到了一个指定的地方。如果我们只是想把所有的文件保存到一个文件夹中，或许这样做是为了将这些文件归档，那么我们可以使用find这条命令。通过使用find命令，我们能够根据文件被修改的时间查找到他们的位置，然后复制他们到指定的地方。这条命令看起来是这样：</p><pre><code>find Documents -mtime -30 -exec cp &quot;{}&quot; Backup \\;
</code></pre><p>上面这条命令会在Documents文件夹中查找在过去30天内被修改过的文件。这些文件之后将会被复制到另一个叫Backup的目录中去。<strong>find</strong>命令将会通过调用<strong>cp</strong>命令来执行复制这一操作。通过修改<strong>mtime</strong>这条参数，我们可以查找到最近某个时间内被修改过的文件，在上面这个例子中它被设定为在过去的30天内。</p><p>更多的时候，我们会想要在把文件复制到目标文件夹后，仍然能够保留源文件夹的目录结构。很多时候，人们都希望两个文件夹的内容同步，然后他们会运行一个脚本来使他们保持一致。这种情况下，我们可能会用到<strong>rsync</strong>这条命令了。这个工具会把新文件、修改过的文件从一个复制到另一个目录中去，同时保持源目录的展示结构：</p><pre><code>rsync -a Documents/ Backup
</code></pre><p>上面的例子，它会先找到哪些文件在Documents中和Backup中都存在，以便不再复制这些不必要的文件。</p><p>###第二个场景</p><p><strong>有一个我们都会做的很普遍的工作，就是在一个文本文件中找到一个单词，然后用另一个单词把这个词在文本中的所有实例都替换掉。</strong></p><p>比如，假设我有一个文档中提到一个人名叫“Becky”，但是我后来决定还是用稍微正式点的称呼“Rebecca”为好。对文件中的这个简单的改动，下面这条命令会起到作用：</p><pre><code>perl -pi -e &#39;s/Becky/Rebecca/&#39; mydocument.txt
</code></pre><p>这条微型的Perl脚本会查询文档中所有“Becky”的实例，并且将之改为“Rebecca”。程序首先读取名为mydocument.txt这个要改动的文档，待修改完毕后再保存回去。</p><p>###第三个场景</p><p><strong>一个普遍关注的问题是，在一个硬盘要给别人或者被扔掉之前，需要对其中存储的敏感数据做些什么。</strong></p><p>有些人会在电脑里保存一些银行的业务数据或者税务信息，那么这些数据最好在你的硬盘被转手到别人之前被彻底清理掉。现在有一些方法和工具可以让你使用。我最喜欢的一个是<strong>shred</strong>这条命令，它不仅能对单一文件进行处理，同样也能对整个设备进行处理。要重写一个文件里面的内容，我们可以这样运行<strong>shred</strong>：</p><pre><code>shred mytaxes.odt
</code></pre><p>上面这个例子中，它会移除文件里存的内容，但并不会把文件本身从硬盘中删除掉。如果要清除文件的内容同时删除掉这个文件，我们可以这样运行：</p><pre><code>shred -u mytaxes.odt
</code></pre><p>需要强调的一点是，<strong>shred</strong>并不是在所有的文件系统中都能正常运行，尤其是那些带有日志功能的比较新的文件系统。在<strong>shred</strong>的操作手册中写明了哪些文件系统运行这个程序的时候会出问题。当处理敏感数据的时候，最好的方法也许是清除掉整张硬盘。<strong>shred</strong>同样也能办到。下面这个例子中，显示了如何移除掉我们电脑中第一块硬盘内的所有数据。使用这条命令一定要非常小心：</p><pre><code>shred /dev/sda
</code></pre><hr>`,24)),p("p",null,[t[1]||(t[1]=e("via: ",-1)),s(n,{href:"http://distrowatch.com/weekly.php?issue=20130923"},{default:o(()=>[...t[0]||(t[0]=[e("http://distrowatch.com/weekly.php?issue=20130923",-1)])]),_:1})]),p("p",null,[t[4]||(t[4]=e("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[2]||(t[2]=[e("LCTT",-1)])]),_:1}),t[5]||(t[5]=e(" 原创翻译，",-1)),s(n,{href:"http://linux.cn/portal.php"},{default:o(()=>[...t[3]||(t[3]=[e("Linux中国",-1)])]),_:1}),t[6]||(t[6]=e(" 荣誉推出",-1))]),p("p",null,[t[9]||(t[9]=e("译者：",-1)),s(n,{href:"http://linux.cn/space/markvv"},{default:o(()=>[...t[7]||(t[7]=[e("markvv",-1)])]),_:1}),t[10]||(t[10]=e(" 校对：",-1)),s(n,{href:"http://linux.cn/space/wxy"},{default:o(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})])])}const h=r(l,[["render",u]]);export{C as __pageData,h as default};
